# STOP draws each task's landscape by name from its data file, and Quartic is
# De Jong's f4: it adds U[0,1) on both platforms, so MATLAB and numpy draw
# different numbers and only the deterministic part can match. These are the
# Quartic tasks among the first three of each problem.
NOISY = {("STOP4", 0), ("STOP6", 2), ("STOP8", 1)}


def probe(lower, upper, task_index):
    """The same three points MATLAB builds, in the task's own box."""
    D = len(lower)
    a = np.arange(3)[:, None]
    b = np.arange(D)[None, :]
    frac = ((a * 7 + b * 13 + task_index * 5) % 97 + 0.5) / 97
    return lower + frac * (upper - lower)


def evaluate(name, t):
    mod_name, cls_name, meth = MTOP[name][:3]
    mod = importlib.import_module(f"ddmtolab.Problems.MTSO.{mod_name}")
    problem = getattr(getattr(mod, cls_name)(), meth)()
    info = problem.get_task_info(t)
    lower = np.ravel(info["lower_bounds"]).astype(float)
    upper = np.ravel(info["upper_bounds"]).astype(float)
    X = probe(lower, upper, t)
    obj, con = problem.evaluate_task(t, X)
    return info, X, obj, con


@pytest.mark.parametrize("name", sorted(MTOP))
def test_matches_mtop(name):
    for t, (D, want_obj, want_con) in enumerate(MTOP[name][3]):
        info, X, obj, con = evaluate(name, t)
        assert info["dimension"] == D, f"{name} task {t + 1} dimension"
        if (name, t) in NOISY:
            # same landscape, independent noise: the gap has to land in (-1, 1)
            gap = obj.ravel() - np.array(want_obj)
            assert np.all(np.abs(gap) < 1.0), f"{name} task {t + 1} is more than noise apart"
        else:
            assert np.allclose(obj.ravel(), want_obj, rtol=1e-11, atol=1e-11),                 f"{name} task {t + 1} objectives"
        assert np.allclose(con.ravel(), want_con, rtol=1e-11, atol=1e-11),             f"{name} task {t + 1} constraints"


def test_stop_quartic_is_the_deterministic_part_plus_uniform_noise():
    """STOP4 task 1 is Quartic: sum((x - opt)^4 * i) + U[0, 1), on both sides."""
    info, X, obj, _ = evaluate("STOP4", 0)
    import scipy.io
    import pkgutil
    import io as _io

    raw = pkgutil.get_data("ddmtolab.Problems.MTSO", "data_stop/Quartic-Te-hh2-d50-k49.mat")
    data = scipy.io.loadmat(_io.BytesIO(raw))
    opt = data["target"][0, 0]["x_best"].ravel()
    w = np.arange(1, info["dimension"] + 1)
    noise = obj.ravel() - np.sum(((X - opt) ** 4) * w, axis=1)
    assert np.all(noise >= 0.0) and np.all(noise < 1.0)


def test_manytask_rotations_are_orthogonal():
    """ManyTask_10D builds its own rotations; they have to stay isometries."""
    from ddmtolab.Problems.MTSO.many_task_10d import _random_rotation

    rng = np.random.default_rng(7)
    for _ in range(5):
        Q = _random_rotation(10, rng)
        assert np.allclose(Q @ Q.T, np.eye(10), atol=1e-12)
        assert np.isclose(abs(np.linalg.det(Q)), 1.0)
